WITH base AS (SELECT id, account_type, balance, opened_date, status, FLOOR(balance) AS balance_whole, COALESCE(status, 'UNKNOWN') AS status_clean FROM accounts WHERE opened_date >= DATE '2023-04-11' AND customer_id = 18) SELECT id, account_type, balance, opened_date, status, balance_whole, status_clean, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY opened_date DESC, id ASC) AS event_seq, SUM(balance_whole) OVER (PARTITION BY status) AS status_sum_balance_whole, SUM(balance) OVER (PARTITION BY status ORDER BY balance_whole ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_balance, LAG(balance_whole, 2, 0) OVER (PARTITION BY status, account_type ORDER BY balance ASC, id ASC) AS prev_balance_whole FROM base;
